/*!
 * \file
 * \brief Defines the compiled Mo-99 marginal source-emission laws.
 *
 * LNHB: C. Morillon, M.-M. Be, V. P. Chechev and A. G. Egorov, LNHB/KRI,
 * 2004; 2012 tables. Selected beta-minus source emissions.
 *
 * BetaShape 2.4 (06/2024): experimental 848.1 and 1214.5 keV shapes;
 * calculated shapes otherwise. Conditional bin masses integrate
 * piecewise-linear reference densities; full-support references and finite
 * grids remain distinct.
 *
 * Retained forbidden-transition approximations are selected numerical laws,
 * not experimental shape validation.
 *
 * Delayed daughter-isomer emissions and inseparable prompt/delayed atomic
 * totals are excluded.
 *
 * Physical yields remain independent emissions per parent decay. EC creates
 * no primary; daughter chains and unsupported Auger energy laws are
 * excluded.
 *
 * Selection and exclusions: validation/radioactivity/data/Mo-99/reference/.
 *
 * \author Julien BERT <julien.bert@univ-brest.fr>
 * \author Didier BENOIT <didier.benoit@inserm.fr>
 */

