[[nodiscard]] auto BuildMo99Radionuclide() -> GGEMSRadionuclideDefinition {
  std::vector<GGEMSRadionuclideEmission> emissions;
  emissions.reserve(25U);

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_158_3_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_158_3_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_158_3_keV_bin_width_micro_eV,
      },
      k_beta_minus_158_3_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_185_2_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_185_2_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_185_2_keV_bin_width_micro_eV,
      },
      k_beta_minus_185_2_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_215_3_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_215_3_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_215_3_keV_bin_width_micro_eV,
      },
      k_beta_minus_215_3_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_228_1_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_228_1_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_228_1_keV_bin_width_micro_eV,
      },
      k_beta_minus_228_1_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_285_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_285_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_285_keV_bin_width_micro_eV,
      },
      k_beta_minus_285_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_353_1_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_353_1_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_353_1_keV_bin_width_micro_eV,
      },
      k_beta_minus_353_1_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_436_6_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_436_6_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_436_6_keV_bin_width_micro_eV,
      },
      k_beta_minus_436_6_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_685_7_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_685_7_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_685_7_keV_bin_width_micro_eV,
      },
      k_beta_minus_685_7_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_822_8_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_822_8_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_822_8_keV_bin_width_micro_eV,
      },
      k_beta_minus_822_8_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_848_1_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_848_1_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_848_1_keV_bin_width_micro_eV,
      },
      k_beta_minus_848_1_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_1214_5_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_1214_5_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_1214_5_keV_bin_width_micro_eV,
      },
      k_beta_minus_1214_5_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Gamma, k_nuclear_gamma_yield,
    sources::GGEMSEnergyDistribution::BuildDiscreteLines(
      k_nuclear_gamma_energies_micro_eV, k_nuclear_gamma_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_40_58323_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_40_58323_keV_energies_micro_eV,
                           k_conversion_40_58323_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_181_068_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_181_068_keV_energies_micro_eV,
                           k_conversion_181_068_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_242_29_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_242_29_keV_energies_micro_eV,
                           k_conversion_242_29_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_366_421_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_366_421_keV_energies_micro_eV,
                           k_conversion_366_421_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_380_13_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_380_13_keV_energies_micro_eV,
                           k_conversion_380_13_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_410_27_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_410_27_keV_energies_micro_eV,
                           k_conversion_410_27_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_411_491_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_411_491_keV_energies_micro_eV,
                           k_conversion_411_491_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_457_6_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_457_6_keV_energies_micro_eV,
                           k_conversion_457_6_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_528_788_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_528_788_keV_energies_micro_eV,
                           k_conversion_528_788_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_621_773_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_621_773_keV_energies_micro_eV,
                           k_conversion_621_773_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_739_5_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_739_5_keV_energies_micro_eV,
                           k_conversion_739_5_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_777_921_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_777_921_keV_energies_micro_eV,
                           k_conversion_777_921_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_822_972_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_822_972_keV_energies_micro_eV,
                           k_conversion_822_972_keV_line_yields));

  return {"Mo-99", k_half_life_seconds, std::move(emissions)};
}

